use crate::content::{Bytes, Chunk, IdentRef};
use crate::error::Result;
use crate::ids::{ByteRange, EntityId};
use crate::lang::Resolution;

use super::extract;

#[derive(Clone, Copy)]
enum Hole {
    Child(EntityId),
    Name(EntityId),
}

pub fn bytes_from_span(
    src: &[u8],
    extent: ByteRange,
    children: &[(ByteRange, EntityId)],
    own_name: Option<(ByteRange, EntityId)>,
    resolution: &Resolution,
    item: tree_sitter::Node<'_>,
) -> Result<Bytes> {
    let mut holes: Vec<(ByteRange, Hole)> = children
        .iter()
        .map(|(r, id)| (*r, Hole::Child(*id)))
        .collect();
    if let Some((r, id)) = own_name {
        holes.push((r, Hole::Name(id)));
    }
    for (r, ident) in &resolution.refs {
        if let IdentRef::Entity(id) = ident
            && *id != EntityId::SELF
        {
            holes.push((*r, Hole::Name(*id)));
        }
    }
    holes.sort_by_key(|(r, _)| r.start);
    holes.retain(|(r, _)| r.start >= extent.start && r.end <= extent.end && r.end > r.start);

    let mut used: Vec<(ByteRange, Hole)> = Vec::new();
    let mut out_src = Vec::new();
    let mut chunks = Vec::new();
    let mut pos = extent.start;
    for (r, hole) in &holes {
        if r.start < pos {
            continue;
        }
        if r.start > pos {
            emit_lit(src, pos, r.start, &mut out_src, &mut chunks);
        }
        match hole {
            Hole::Child(id) => chunks.push(Chunk::Child(*id)),
            Hole::Name(id) => {
                if let Some(field) = shorthand_field_spelling(item, src, *r) {
                    chunks.push(Chunk::ShorthandName {
                        id: *id,
                        field,
                    });
                } else {
                    chunks.push(Chunk::Name(*id));
                }
            }
        }
        used.push((*r, *hole));
        pos = r.end;
    }
    if pos < extent.end {
        emit_lit(src, pos, extent.end, &mut out_src, &mut chunks);
    }

    let local_ranges = remap_locals(extent, &used, resolution);
    Bytes::new(out_src, chunks, local_ranges)
}

fn emit_lit(src: &[u8], start: u32, end: u32, out: &mut Vec<u8>, chunks: &mut Vec<Chunk>) {
    let a = start as usize;
    let b = end as usize;
    if a >= b || b > src.len() {
        return;
    }
    let lo = out.len() as u32;
    out.extend_from_slice(&src[a..b]);
    let hi = out.len() as u32;
    if hi > lo {
        chunks.push(Chunk::Literal(ByteRange { start: lo, end: hi }));
    }
}

/// `S { item }` wraps a value identifier whose span is also the field name.
fn shorthand_field_spelling(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    r: ByteRange,
) -> Option<Box<str>> {
    let node = extract::find_node(item, r)?;
    let shorthand = if node.kind() == "shorthand_field_initializer" {
        true
    } else {
        node.parent()
            .is_some_and(|p| p.kind() == "shorthand_field_initializer")
    };
    if !shorthand {
        return None;
    }
    Some(String::from_utf8_lossy(&src[r.start as usize..r.end as usize]).into())
}

fn remap_locals(
    extent: ByteRange,
    holes: &[(ByteRange, Hole)],
    resolution: &Resolution,
) -> Vec<(ByteRange, IdentRef)> {
    let mut out = Vec::new();
    let push = |r: ByteRange, ident: IdentRef, out: &mut Vec<(ByteRange, IdentRef)>| {
        if r.start < extent.start || r.end > extent.end {
            return;
        }
        if holes
            .iter()
            .any(|(h, _)| r.start >= h.start && r.end <= h.end)
        {
            return;
        }
        let skipped: u32 = holes
            .iter()
            .filter(|(h, _)| h.end <= r.start)
            .map(|(h, _)| h.len())
            .sum();
        let base = match r.start.checked_sub(extent.start) {
            Some(b) if skipped <= b => b - skipped,
            _ => return,
        };
        let end_base = match r.end.checked_sub(extent.start) {
            Some(b) if skipped <= b => b - skipped,
            _ => return,
        };
        if end_base <= base {
            return;
        }
        out.push((
            ByteRange {
                start: base,
                end: end_base,
            },
            ident,
        ));
    };
    for (r, slot, ns) in &resolution.slots {
        push(*r, IdentRef::Local(*slot, *ns), &mut out);
    }
    for (r, ident) in &resolution.refs {
        if matches!(ident, IdentRef::Local(_, _) | IdentRef::Free(_)) {
            push(*r, ident.clone(), &mut out);
        }
    }
    out
}

crates/svc-core/src/engine/canon.rs.Text:
use std::collections::HashMap;

use super::extract::{byte_range, is_extracted_item};
use crate::content::{Content, IdentRef, Namespace, Token};
use crate::error::Result;
use crate::ids::{ByteRange, EntityId, Slot};
use crate::lang::{Env, Lang, Locator, Resolution, Role, When};

pub fn canonicalize(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    res: &Resolution,
    children: &[(ByteRange, EntityId)],
    lang: &dyn Lang,
) -> Result<Content> {
    let mut tokens = Vec::new();
    let binders = binders_from_res(res);
    let attached = file_attached_nodes(item, lang);
    let item_start = item.start_byte();
    for extra in &attached {
        if extra.start_byte() < item_start {
            walk(
                *extra,
                item,
                src,
                lang,
                children,
                res,
                &binders,
                &mut tokens,
            );
        }
    }
    walk(item, item, src, lang, children, res, &binders, &mut tokens);
    for extra in &attached {
        if extra.start_byte() >= item_start {
            walk(
                *extra,
                item,
                src,
                lang,
                children,
                res,
                &binders,
                &mut tokens,
            );
        }
    }
    Ok(Content { tokens })
}

fn binders_from_res(res: &Resolution) -> HashMap<(u32, u32), (Slot, Namespace)> {
    let mut m = HashMap::new();
    for (r, slot, ns) in &res.slots {
        m.insert((r.start, r.end), (*slot, *ns));
    }
    m
}

pub fn resolve_locals(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> Resolution {
    let mut slots = Vec::new();
    let mut binders = Vec::new();
    let mut next: HashMap<Namespace, u32> = HashMap::new();
    inherit_outer_generics(item, src, lang, &mut slots, &mut binders, &mut next);
    collect_binders(
        item,
        src,
        lang,
        None,
        &mut slots,
        &mut binders,
        &mut next,
        item.id(),
    );
    let slot_at: HashMap<(u32, u32), (Slot, Namespace)> = slots
        .iter()
        .map(|(r, s, ns)| ((r.start, r.end), (*s, *ns)))
        .collect();
    let mut refs = Vec::new();
    collect_refs(
        item,
        src,
        lang,
        None,
        &slot_at,
        &binders,
        env,
        &mut refs,
        item.id(),
    );
    // File-tail / inter-item statements are not entities. Resolve them as
    // part of the neighbouring file-root so `rename` rewrites uses there.
    // Walk extras against their own binders: the file-root's name must stay
    // an Entity hole (Local would remain a literal in this item's bytes).
    let mut extra_binders = Vec::new();
    let extra_binder_start = slots.len();
    for extra in file_attached_nodes(item, lang) {
        collect_binders(
            extra,
            src,
            lang,
            None,
            &mut slots,
            &mut extra_binders,
            &mut next,
            extra.id(),
        );
    }
    let extra_slot_at: HashMap<(u32, u32), (Slot, Namespace)> = slots[extra_binder_start..]
        .iter()
        .map(|(r, s, ns)| ((r.start, r.end), (*s, *ns)))
        .collect();
    for extra in file_attached_nodes(item, lang) {
        collect_refs(
            extra,
            src,
            lang,
            None,
            &extra_slot_at,
            &extra_binders,
            env,
            &mut refs,
            extra.id(),
        );
    }
    Resolution { slots, refs }
}

/// Named file-level statements owned by this file-root but not part of its
/// item node: preceding kindless statements (in this entity's bytes, which
/// start where the previous file-root's item ended) and, when this is the
/// last file-root, following tail statements through EOF.
fn file_attached_nodes<'a>(
    item: tree_sitter::Node<'a>,
    lang: &dyn Lang,
) -> Vec<tree_sitter::Node<'a>> {
    if !is_extracted_item(item, lang) || !is_file_root_item(item, lang) {
        return Vec::new();
    }
    let root = syntax_root(item);
    let stmt = top_level_under(item, root);
    let mut children = Vec::new();
    let mut c = root.walk();
    for ch in root.named_children(&mut c) {
        children.push(ch);
    }
    let Some(idx) = children.iter().position(|ch| ch.id() == stmt.id()) else {
        return Vec::new();
    };
    let prev_entity = (0..idx)
        .rev()
        .find(|&i| subtree_has_extracted_entity(children[i], lang));
    let next_entity =
        ((idx + 1)..children.len()).find(|&i| subtree_has_extracted_entity(children[i], lang));
    let start = prev_entity.map(|i| i + 1).unwrap_or(0);
    let last = next_entity.is_none();
    let mut out = Vec::new();
    for (i, ch) in children.into_iter().enumerate() {
        if i == idx {
            continue;
        }
        if i < start {
            continue;
        }
        if i < idx {
            out.push(ch);
            continue;
        }
        if last {
            out.push(ch);
        }
    }
    out
}

fn is_file_root_item(item: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    let mut p = item.parent();
    while let Some(parent) = p {
        if is_extracted_item(parent, lang) {
            return false;
        }
        p = parent.parent();
    }
    true
}

fn syntax_root(item: tree_sitter::Node<'_>) -> tree_sitter::Node<'_> {
    let mut n = item;
    while let Some(p) = n.parent() {
        n = p;
    }
    n
}

fn top_level_under<'a>(
    item: tree_sitter::Node<'a>,
    root: tree_sitter::Node<'a>,
) -> tree_sitter::Node<'a> {
    let mut n = item;
    while let Some(p) = n.parent() {
        if p.id() == root.id() {
            return n;
        }
        n = p;
    }
    item
}

fn subtree_has_extracted_entity(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    if is_extracted_item(node, lang) {
        return true;
    }
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        if subtree_has_extracted_entity(ch, lang) {
            return true;
        }
    }
    false
}

#[derive(Clone)]
struct BinderInfo {
    range: ByteRange,
    visible_from: u32,
    scope: ByteRange,
    slot: Slot,
    namespace: Namespace,
    name: String,
}

fn collect_binders<'a>(
    node: tree_sitter::Node<'a>,
    src: &[u8],
    lang: &dyn Lang,
    field: Option<&str>,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
    root_id: usize,
) {
    if skip_nested_item(node, lang, root_id) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != root_id {
        return;
    }
    for role in lang.roles(node, field, src, &crate::lang::Env::default()) {
        if let Role::Binder {
            namespace,
            visibility,
            locator,
        } = role
        {
            for name_node in locate(node, locator) {
                for id in ident_leaves(name_node, name_node, src) {
                    let r = byte_range(id);
                    // Typed `|x: T|` is both a `parameter` binder and a child of
                    // `closure_parameters`. One range, one slot.
                    if slots.iter().any(|(existing, _, _)| *existing == r) {
                        continue;
                    }
                    let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize])
                        .into_owned();
                    // `Ok(x) | Err(x)` is one binding. Fresh slots per occurrence
                    // make O9 rename them apart and rustc reject the or-pattern.
                    let slot =
                        or_pattern_slot(id, &name, namespace, binders).unwrap_or_else(|| {
                            let n = next.entry(namespace).or_insert(0);
                            let slot = Slot(*n);
                            *n += 1;
                            slot
                        });
                    slots.push((r, slot, namespace));
                    let (visible_from, scope) = binder_extent(node, src, lang, root_id, visibility);
                    binders.push(BinderInfo {
                        range: r,
                        visible_from,
                        scope,
                        slot,
                        namespace,
                        name,
                    });
                }
            }
        }
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            collect_binders(
                c.node(),
                src,
                lang,
                c.field_name(),
                slots,
                binders,
                next,
                root_id,
            );
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn collect_refs<'a>(
    node: tree_sitter::Node<'a>,
    src: &[u8],
    lang: &dyn Lang,
    field: Option<&str>,
    slot_at: &HashMap<(u32, u32), (Slot, Namespace)>,
    binders: &[BinderInfo],
    env: &Env,
    refs: &mut Vec<(ByteRange, IdentRef)>,
    root_id: usize,
) {
    if skip_nested_item(node, lang, root_id) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != root_id {
        return;
    }
    if is_inherent_method_ref(node, src) {
        let r = byte_range(node);
        let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]).into_owned();
        if let Some(id) = env.self_methods.get(&name) {
            refs.push((r, IdentRef::Entity(*id)));
        } else {
            refs.push((r, IdentRef::Free(name.into())));
        }
        return;
    }
    if is_ident_leaf(node) {
        let r = byte_range(node);
        if slot_at.contains_key(&(r.start, r.end)) {
            // declaration site recorded as slot, not a ref
        } else {
            let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]).into_owned();
            let ns = lang
                .roles(node, field, src, &crate::lang::Env::default())
                .into_iter()
                .find_map(|role| match role {
                    Role::Reference { namespace } => Some(namespace),
                    _ => None,
                })
                .unwrap_or(match node.kind() {
                    "type_identifier" | "primitive_type" => Namespace::Type,
                    "lifetime" => Namespace::Lifetime,
                    _ => Namespace::Value,
                });
            let local = binders
                .iter()
                .filter(|b| {
                    b.name == name
                        && b.namespace == ns
                        && b.visible_from <= r.start
                        && b.scope.start <= r.start
                        && r.end <= b.scope.end
                        && !blocked_by_barrier(node, b, ns, src, lang, root_id)
                })
                .max_by_key(|b| (b.scope.start, b.range.start));
            if is_struct_field_key(node) || is_dot_field(node) || is_type_binding_name(node) {
                refs.push((r, IdentRef::Free(name.into())));
            } else if let Some(binder) =
                local.filter(|_| !is_rust_nonlocal_ident(node, lang))
            {
                refs.push((r, IdentRef::Local(binder.slot, ns)));
            } else if is_foreign_scoped_ref(node, src, lang, env)
                || is_type_qualified_ref(node, src, lang, env)
            {
                refs.push((r, IdentRef::Free(name.into())));
            } else if let Some(id) = env.lookup(&name, ns) {
                refs.push((r, IdentRef::Entity(id)));
            } else {
                refs.push((r, IdentRef::Free(name.into())));
            }
        }
        return;
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            collect_refs(
                c.node(),
                src,
                lang,
                c.field_name(),
                slot_at,
                binders,
                env,
                refs,
                root_id,
            );
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn locate<'a>(node: tree_sitter::Node<'a>, loc: Locator) -> Vec<tree_sitter::Node<'a>> {
    match loc {
        Locator::Itself => vec![node],
        Locator::Field(f) => node.child_by_field_name(f).into_iter().collect(),
        Locator::ChildIndex(i) => node.named_child(i as u32).into_iter().collect(),
        Locator::FieldWithKind(f, k) => node
            .child_by_field_name(f)
            .filter(|n| n.kind() == k)
            .into_iter()
            .collect(),
    }
}

fn ident_leaves<'a>(
    node: tree_sitter::Node<'a>,
    pattern_root: tree_sitter::Node<'a>,
    src: &[u8],
) -> Vec<tree_sitter::Node<'a>> {
    if is_ident_leaf(node) {
        let t = node.kind();
        if t == "_" || node_is_wildcard(node) {
            return vec![];
        }
        return (!is_pattern_constructor(node, pattern_root, src))
            .then_some(node)
            .into_iter()
            .collect();
    }
    if node.kind() == "match_pattern" {
        let mut out = Vec::new();
        let mut c = node.walk();
        if c.goto_first_child() {
            loop {
                if c.field_name() != Some("condition") {
                    out.extend(ident_leaves(c.node(), pattern_root, src));
                }
                if !c.goto_next_sibling() {
                    break;
                }
            }
        }
        return out;
    }
    let mut out = Vec::new();
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        out.extend(ident_leaves(ch, pattern_root, src));
    }
    out
}

fn binder_extent(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
    visibility: crate::lang::Visibility,
) -> (u32, ByteRange) {
    match visibility {
        crate::lang::Visibility::AfterStmt => {
            let visible_from = node.end_byte() as u32;
            if node.kind() == "let_condition" {
                if let Some(parent) = node.parent() {
                    let end = match parent.kind() {
                        "if_expression" => parent
                            .child_by_field_name("consequence")
                            .map(|c| c.end_byte() as u32),
                        "while_expression" => {
                            parent.child_by_field_name("body").map(|c| c.end_byte() as u32)
                        }
                        _ => None,
                    };
                    if let Some(end) = end {
                        return (
                            visible_from,
                            ByteRange {
                                start: visible_from,
                                end,
                            },
                        );
                    }
                }
            }
            (visible_from, enclosing_scope(node, src, lang, root_id))
        }
        crate::lang::Visibility::Hoisted => {
            let scope = enclosing_var_scope(node, src, lang, root_id);
            (scope.start, scope)
        }
        crate::lang::Visibility::Sub(fields) => {
            let scope = sub_field_scope(node, fields)
                .unwrap_or_else(|| enclosing_scope(node, src, lang, root_id));
            (scope.start, scope)
        }
        crate::lang::Visibility::Whole => {
            let scope = enclosing_scope(node, src, lang, root_id);
            (scope.start, scope)
        }
    }
}

fn enclosing_var_scope(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> ByteRange {
    if lang.name() != "javascript" {
        return enclosing_scope(node, src, lang, root_id);
    }
    let mut current = node.parent();
    while let Some(parent) = current {
        if is_js_var_scope(parent.kind()) {
            return byte_range(parent);
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    enclosing_scope(node, src, lang, root_id)
}

fn is_js_var_scope(kind: &str) -> bool {
    matches!(
        kind,
        "program"
            | "function_declaration"
            | "generator_function_declaration"
            | "function_expression"
            | "generator_function"
            | "method_definition"
            | "arrow_function"
            | "class_static_block"
    )
}

fn sub_field_scope(node: tree_sitter::Node<'_>, fields: &[&str]) -> Option<ByteRange> {
    let mut current = Some(node);
    while let Some(n) = current {
        let mut start = u32::MAX;
        let mut end = 0u32;
        let mut found = false;
        for field in fields {
            if let Some(child) = n.child_by_field_name(field) {
                let r = byte_range(child);
                start = start.min(r.start);
                end = end.max(r.end);
                found = true;
            }
        }
        if found {
            return Some(ByteRange { start, end });
        }
        current = n.parent();
    }
    None
}

fn enclosing_scope(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> ByteRange {
    let mut current = node.parent();
    while let Some(parent) = current {
        if lang
            .roles(parent, None, src, &crate::lang::Env::default())
            .iter()
            .any(|role| matches!(role, Role::Scope { .. }))
        {
            return byte_range(parent);
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    let mut root = node;
    while root.id() != root_id {
        root = root.parent().expect("resolver node belongs to root");
    }
    byte_range(root)
}

fn blocked_by_barrier(
    from: tree_sitter::Node<'_>,
    binder: &BinderInfo,
    ns: Namespace,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> bool {
    let mut current = from.parent();
    while let Some(parent) = current {
        for role in lang.roles(parent, None, src, &crate::lang::Env::default()) {
            if let Role::Scope { barriers, .. } = role {
                let blocks = barriers
                    .iter()
                    .any(|b| b.ns == ns && b.when == When::Always);
                if blocks {
                    let scope = byte_range(parent);
                    let inside = scope.start <= binder.range.start && binder.range.end <= scope.end;
                    if !inside {
                        return true;
                    }
                }
            }
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    false
}

/// Nested entities are skipped, so `When::ThroughBlock` cannot be applied by
/// walking into them. Copy ancestor `type_parameters` onto this item only when
/// the path does not go through a `block` (impl/trait methods inherit `T`;
/// a nested `fn` inside `fn f<T>` does not).
fn inherit_outer_generics(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
) {
    let scope = byte_range(item);
    let mut ancestor = item.parent();
    while let Some(node) = ancestor {
        if let Some(tp) = node.child_by_field_name("type_parameters") {
            if !crosses_block(node, item) {
                add_generic_binders(tp, src, lang, scope, slots, binders, next);
            }
        }
        ancestor = node.parent();
    }
}

fn crosses_block(ancestor: tree_sitter::Node<'_>, item: tree_sitter::Node<'_>) -> bool {
    let mut current = item.parent();
    while let Some(node) = current {
        if node.id() == ancestor.id() {
            return false;
        }
        if node.kind() == "block" {
            return true;
        }
        current = node.parent();
    }
    false
}

fn add_generic_binders(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    scope: ByteRange,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
) {
    if matches!(
        node.kind(),
        "type_parameter" | "lifetime_parameter" | "const_parameter"
    ) {
        for role in lang.roles(node, None, src, &Env::default()) {
            if let Role::Binder {
                namespace, locator, ..
            } = role
            {
                for name_node in locate(node, locator) {
                    for id in ident_leaves(name_node, name_node, src) {
                        let r = byte_range(id);
                        let n = next.entry(namespace).or_insert(0);
                        let slot = Slot(*n);
                        *n += 1;
                        slots.push((r, slot, namespace));
                        binders.push(BinderInfo {
                            range: r,
                            visible_from: scope.start,
                            scope,
                            slot,
                            namespace,
                            name: String::from_utf8_lossy(&src[r.start as usize..r.end as usize])
                                .into_owned(),
                        });
                    }
                }
            }
        }
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            add_generic_binders(c.node(), src, lang, scope, slots, binders, next);
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn is_pattern_constructor(
    node: tree_sitter::Node<'_>,
    pattern_root: tree_sitter::Node<'_>,
    src: &[u8],
) -> bool {
    let mut current = node;
    while current.id() != pattern_root.id() {
        let Some(parent) = current.parent() else {
            break;
        };
        match parent.kind() {
            "tuple_struct_pattern" | "struct_pattern" => {
                if parent.child_by_field_name("type").is_some_and(|n| {
                    n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte()
                }) {
                    return true;
                }
            }
            "scoped_identifier" | "scoped_type_identifier" | "generic_pattern" => {
                return true;
            }
            "field_pattern" => {
                if node.kind() != "shorthand_field_identifier"
                    && parent.child_by_field_name("name").is_some_and(|n| {
                        n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte()
                    })
                {
                    return true;
                }
            }
            "captured_pattern" => {
                if parent.named_child(0).is_some_and(|n| n.id() == node.id()) {
                    return false;
                }
            }
            _ => {}
        }
        current = parent;
    }
    // Unit variants / consts (`None`, `AfterStmt`) are identifier patterns.
    // Bindings in this crate are snake_case; PascalCase is the constructor.
    if node.kind() == "identifier" {
        let name = &src[node.start_byte()..node.end_byte()];
        if name.first().is_some_and(|b| b.is_ascii_uppercase()) {
            return true;
        }
    }
    false
}

fn or_pattern_slot(
    ident: tree_sitter::Node<'_>,
    name: &str,
    ns: Namespace,
    binders: &[BinderInfo],
) -> Option<Slot> {
    let mut current = ident.parent();
    while let Some(parent) = current {
        if parent.kind() == "or_pattern" {
            let start = parent.start_byte() as u32;
            let end = parent.end_byte() as u32;
            if let Some(b) = binders.iter().rev().find(|b| {
                b.namespace == ns && b.name == name && start <= b.range.start && b.range.end <= end
            }) {
                return Some(b.slot);
            }
        }
        current = parent.parent();
    }
    None
}

fn is_struct_field_key(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if parent.kind() != "field_initializer" {
        return false;
    }
    parent.child_by_field_name("field").is_some_and(|f| {
        f.id() == node.id()
            || (f.start_byte() <= node.start_byte() && node.end_byte() <= f.end_byte())
    })
}

/// `It<Item = T>`: the left `Item` is an associated-type binding name, not a
/// reference to a type `Item` in scope (SPEC §9; needs the receiver's type).
fn is_type_binding_name(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if parent.kind() != "type_binding" {
        return false;
    }
    parent.child_by_field_name("name").is_some_and(|n| {
        n.id() == node.id()
            || (n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte())
    })
}

/// `.src` is a field or method name, including inside `vec![self.src.len()]`
/// where the path is a flat `token_tree`. A same-named local must not win.
fn is_dot_field(node: tree_sitter::Node<'_>) -> bool {
    let mut prev = node.prev_sibling();
    while let Some(n) = prev {
        if n.kind() == "." {
            return true;
        }
        if n.is_named() {
            return false;
        }
        prev = n.prev_sibling();
    }
    false
}

fn is_rust_nonlocal_ident(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    let mut current = node;
    while let Some(parent) = current.parent() {
        if matches!(
            parent.kind(),
            "scoped_identifier" | "scoped_type_identifier"
        ) {
            return true;
        }
        if matches!(
            parent.kind(),
            "block" | "function_item" | "function_signature_item"
        ) {
            break;
        }
        current = parent;
    }
    false
}

/// `RedbStore::open` is not a free `fn open`. Type-relative names stay Free
/// (SPEC §9) unless they are same-impl inherent methods (earlier) or the
/// qualifier is `Self` / the enclosing impl or trait (`S::Item` / `T::Item` /
/// `Tr::Item` in `impl Tr for S` is the associated type, not a free `Item`).
fn is_type_qualified_ref(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    if under_use_tree(node) {
        return false;
    }
    let Some(parent) = node.parent() else {
        return false;
    };
    if !matches!(
        parent.kind(),
        "scoped_identifier" | "scoped_type_identifier"
    ) {
        return false;
    }
    if parent.child_by_field_name("name").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(path) = parent.child_by_field_name("path") else {
        return false;
    };
    let Some(qual) = scoped_qualifier(path) else {
        return false;
    };
    let name = std::str::from_utf8(&src[qual.start_byte()..qual.end_byte()]).unwrap_or("");
    if matches!(name, "crate" | "super" | "self" | "Self") {
        return false;
    }
    if Some(name.as_bytes()) == enclosing_impl_type_name(node, src)
        || Some(name.as_bytes()) == enclosing_impl_trait_name(node, src)
    {
        return false;
    }
    env.lookup_global(name, Namespace::Type).is_some()
}

fn scoped_qualifier(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    loop {
        match node.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                node = node.child_by_field_name("name")?;
            }
            "generic_type" => {
                node = node.child_by_field_name("type")?;
            }
            "bracketed_type" => {
                node = node.named_child(0)?;
            }
            "qualified_type" => {
                node = node.child_by_field_name("type")?;
            }
            _ => return Some(node),
        }
    }
}

fn under_use_tree(mut node: tree_sitter::Node<'_>) -> bool {
    while let Some(parent) = node.parent() {
        if matches!(
            parent.kind(),
            "use_declaration" | "use_as_clause" | "use_list" | "use_wildcard"
        ) {
            return true;
        }
        node = parent;
    }
    false
}

/// `axum::response` is not our `fn response` in another file. If the leftmost
/// path segment is not `crate`/`super`/`self` and is not an entity, every
/// later segment is Free. `use crate::a::f` must not look foreign: wrapping
/// `use` nodes are not the path root.
fn is_foreign_scoped_ref(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    let Some(root) = scoped_path_root(node) else {
        return false;
    };
    if root.id() == node.id() {
        return false;
    }
    let name = std::str::from_utf8(&src[root.start_byte()..root.end_byte()]).unwrap_or("");
    if matches!(name, "crate" | "super" | "self" | "Self") {
        return false;
    }
    env.lookup_global(name, Namespace::Value).is_none()
        && env.lookup_global(name, Namespace::Type).is_none()
}

fn scoped_path_root(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    let mut saw_scoped = false;
    while let Some(parent) = node.parent() {
        match parent.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                saw_scoped = true;
                node = parent;
            }
            // `use crate::a::f` / `use crate::a::g as gg`: stop at the wrapper so
            // the root stays `crate`, not the whole use line (which looks foreign).
            _ => break,
        }
    }
    if !saw_scoped {
        return None;
    }
    loop {
        match node.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                node = node.child_by_field_name("path")?;
            }
            "bracketed_type" => {
                node = node.named_child(0)?;
            }
            "qualified_type" => {
                node = node.child_by_field_name("type")?;
            }
            "generic_type" => {
                node = node.child_by_field_name("type")?;
            }
            _ => return Some(node),
        }
    }
}

fn node_is_wildcard(node: tree_sitter::Node<'_>) -> bool {
    matches!(node.kind(), "_" | "remaining_field_pattern")
}

/// Nested `function`/`class`/`impl` items are separate entities. JS
/// `variable_declarator` is an entity kind at module scope only; inside a
/// function it is a local and must not be a resolver barrier.
fn skip_nested_item(node: tree_sitter::Node<'_>, lang: &dyn Lang, root_id: usize) -> bool {
    if node.id() == root_id {
        return false;
    }
    if node.kind() == "variable_declarator" {
        return false;
    }
    lang.entity_kinds()
        .iter()
        .any(|r| r.node_kind == node.kind())
}

fn is_opaque_node(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    lang.opaque_nodes().iter().any(|k| *k == node.kind())
}

/// Method name of `self.foo()`, `Self::foo()`, `S::foo()` inside `impl S`, or JS
/// `self.foo()` / `Self::foo` / `Self::N` / `this.foo()` — bound to a sibling
/// under the enclosing impl/class, not the flat Value env (a free `fn foo` is
/// a different target). `x.foo()` stays Free: that needs types.
fn is_inherent_method_ref(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    match node.kind() {
        "field_identifier" => rust_self_field_call(node),
        "property_identifier" => js_this_member_call(node),
        "identifier" => rust_self_path_method(node, src),
        _ => false,
    }
}

fn rust_self_field_call(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent().filter(|p| p.kind() == "field_expression") else {
        return false;
    };
    if parent.child_by_field_name("field").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(value) = parent.child_by_field_name("value") else {
        return false;
    };
    if value.kind() != "self" {
        return false;
    }
    let Some(grand) = parent.parent() else {
        return false;
    };
    grand.kind() == "call_expression"
        && grand.child_by_field_name("function").map(|n| n.id()) == Some(parent.id())
}

fn js_this_member_call(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent().filter(|p| p.kind() == "member_expression") else {
        return false;
    };
    if parent.child_by_field_name("property").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(object) = parent.child_by_field_name("object") else {
        return false;
    };
    if object.kind() != "this" {
        return false;
    }
    let Some(grand) = parent.parent() else {
        return false;
    };
    grand.kind() == "call_expression"
        && grand.child_by_field_name("function").map(|n| n.id()) == Some(parent.id())
}

fn rust_self_path_method(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    let Some(parent) = node.parent().filter(|p| p.kind() == "scoped_identifier") else {
        return false;
    };
    if parent.child_by_field_name("name").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(path) = parent.child_by_field_name("path") else {
        return false;
    };
    let Some(qual) = scoped_qualifier(path) else {
        return false;
    };
    let start = qual.start_byte();
    let end = qual.end_byte();
    if end > src.len() || start >= end {
        return false;
    }
    let path_text = &src[start..end];
    if path_text != b"Self"
        && Some(path_text) != enclosing_impl_type_name(node, src)
        && Some(path_text) != enclosing_impl_trait_name(node, src)
    {
        return false;
    }
    true
}

/// The `Self` type of the enclosing `impl` (`S` in `impl S` / `impl Trait for S` /
/// `impl<T> S<T>`), or the enclosing trait name (`T` in `trait T`). Used so
/// `S::foo()` / `T::Item` bind like `Self::foo()` / `Self::Item`.
fn enclosing_impl_type_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        let Some(parent) = node.parent() else {
            return None;
        };
        if parent.kind() == "impl_item" {
            return parent
                .child_by_field_name("type")
                .and_then(|ty| impl_type_base_name(ty, src));
        }
        if parent.kind() == "trait_item" {
            return parent
                .child_by_field_name("name")
                .and_then(|n| impl_type_base_name(n, src));
        }
        node = parent;
    }
}

/// The trait in `impl Trait for S`, so `Tr::Item` / `Tr::foo` inside that impl
/// bind like `Self::Item` / `Self::foo`.
fn enclosing_impl_trait_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        let Some(parent) = node.parent() else {
            return None;
        };
        if parent.kind() == "impl_item" {
            return parent
                .child_by_field_name("trait")
                .and_then(|ty| impl_type_base_name(ty, src));
        }
        node = parent;
    }
}

fn impl_type_base_name<'a>(ty: tree_sitter::Node<'a>, src: &'a [u8]) -> Option<&'a [u8]> {
    match ty.kind() {
        "type_identifier" | "identifier" => {
            let start = ty.start_byte();
            let end = ty.end_byte();
            (end <= src.len() && start < end).then(|| &src[start..end])
        }
        "generic_type" => ty
            .child_by_field_name("type")
            .and_then(|inner| impl_type_base_name(inner, src)),
        "scoped_type_identifier" => ty
            .child_by_field_name("name")
            .and_then(|inner| impl_type_base_name(inner, src)),
        _ => None,
    }
}

fn is_doc_attribute(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    let Some(attr) = node.named_child(0).filter(|n| n.kind() == "attribute") else {
        return false;
    };
    let Some(path) = attr.named_child(0) else {
        return false;
    };
    &src[path.start_byte()..path.end_byte()] == b"doc"
}

fn is_ident_leaf(node: tree_sitter::Node<'_>) -> bool {
    matches!(
        node.kind(),
        "identifier"
            | "type_identifier"
            | "primitive_type"
            | "self"
            | "super"
            | "crate"
            | "lifetime"
            | "label"
            | "statement_identifier"
            | "shorthand_field_identifier"
            | "shorthand_property_identifier"
            | "shorthand_property_identifier_pattern"
    )
}

fn walk(
    node: tree_sitter::Node<'_>,
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    children: &[(ByteRange, EntityId)],
    res: &Resolution,
    binders: &HashMap<(u32, u32), (Slot, Namespace)>,
    tokens: &mut Vec<Token>,
) {
    if node.id() != item.id() {
        if let Some(id) = child_id(node, children) {
            tokens.push(Token::Child(id));
            return;
        }
    }
    if matches!(node.kind(), "attribute_item" | "inner_attribute_item") {
        if !is_doc_attribute(node, src) {
            let r = byte_range(node);
            let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
            if !text.trim().is_empty() {
                tokens.push(Token::Lit(text.as_ref().into()));
            }
        }
        return;
    }
    if lang.trivia_kinds().iter().any(|k| *k == node.kind()) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != item.id() {
        let r = byte_range(node);
        let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
        if !text.trim().is_empty() {
            tokens.push(Token::Lit(text.as_ref().into()));
        }
        return;
    }
    if node.child_count() == 0 {
        if let Some(tok) = leaf_token(node, src, item, lang, res, binders) {
            tokens.push(tok);
        }
        return;
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            walk(c.node(), item, src, lang, children, res, binders, tokens);
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn child_id(node: tree_sitter::Node<'_>, children: &[(ByteRange, EntityId)]) -> Option<EntityId> {
    let start = node.start_byte() as u32;
    let end = node.end_byte() as u32;
    children
        .iter()
        .find(|(r, _)| r.end == end && start >= r.start && start <= r.end)
        .map(|(_, id)| *id)
}

fn leaf_token(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    item: tree_sitter::Node<'_>,
    lang: &dyn Lang,
    res: &Resolution,
    binders: &HashMap<(u32, u32), (Slot, Namespace)>,
) -> Option<Token> {
    let r = byte_range(node);
    let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
    if text.trim().is_empty() {
        return None;
    }
    if let Some((slot, ns)) = binders.get(&(r.start, r.end)) {
        return Some(Token::Binder(*slot, *ns));
    }
    if let Some(name) = item.child_by_field_name("name") {
        if byte_range(name) == r {
            return Some(Token::Ident(IdentRef::Entity(EntityId::SELF)));
        }
    }
    for (rr, ident) in &res.refs {
        if *rr == r {
            return Some(Token::Ident(ident.clone()));
        }
    }
    if is_ident_leaf(node)
        || matches!(
            node.kind(),
            "field_identifier" | "property_identifier" | "property_identifier_pattern"
        )
    {
        return Some(Token::Ident(IdentRef::Free(text.as_ref().into())));
    }
    let kind = node.kind();
    if lang.literal_kinds().contains(&kind) {
        Some(Token::Lit(text.as_ref().into()))
    } else if kind.chars().all(|c| c.is_ascii_alphabetic() || c == '_') {
        Some(Token::Kw(text.as_ref().into()))
    } else {
        Some(Token::Punct(text.as_ref().into()))
    }
}

crates/svc-core/src/engine/mod.rs.Text:
use std::collections::{BTreeMap, HashSet};

use crate::content::{Bytes, Content, IdentRef};
use crate::entity::{EntityRecord, FileRecord, Kind, SigKey};
use crate::error::{Error, Result};
use crate::ids::{ByteRange, ChangeId, EntityId, RelPath};
use crate::lang::{Env, Lang, Langs, RawEntity, Resolution};
use crate::snapshot::Snapshot;
use crate::store::Store;

mod align;
mod bytes;
mod canon;
mod classify;
mod diff_impl;
mod extract;
mod merge;
mod ops;
mod render_impl;

pub use classify::{Side, classify, classify_entity};
pub use merge::{lca, merge};
pub use ops::{
    StatusReport, add_def, add_def_at, classify_def, commit_snapshot, delete, edit_def,
    extract_hoist, format_tokens, inline, lookup, lookup_name, move_def, redefine, relocate,
    rename, resolve_add_def_file, rust_langs, show, status_report,
};

#[derive(Clone, Debug, Default)]
pub struct Rendered {
    pub files: BTreeMap<RelPath, Vec<u8>>,
    /// Ranges index the rendered entity buffer. Absent when `with_maps` is false.
    pub maps: Option<BTreeMap<EntityId, Vec<(ByteRange, IdentRef)>>>,
}

pub fn parse(src: &[u8], lang: &dyn Lang) -> Result<tree_sitter::Tree> {
    let mut parser = tree_sitter::Parser::new();
    parser
        .set_language(&lang.language())
        .map_err(|e| Error::Parse(e.to_string()))?;
    parser
        .parse(src, None)
        .ok_or_else(|| Error::Parse("tree-sitter returned None".into()))
}

pub fn extract(tree: &tree_sitter::Tree, src: &[u8], lang: &dyn Lang) -> Result<Vec<RawEntity>> {
    extract::extract(tree, src, lang)
}

/// Name + refined Kind for Muse's JS lane tests (nested `let`s stay locals).
pub fn js_extract_refined_kinds(src: &str) -> Result<Vec<(String, crate::entity::Kind)>> {
    let lang = crate::JsLang;
    let tree = parse(src.as_bytes(), &lang)?;
    Ok(extract(&tree, src.as_bytes(), &lang)?
        .into_iter()
        .map(|e| (e.name, e.kind))
        .collect())
}

pub fn env_from_snapshot(snapshot: &Snapshot) -> Env {
    let mut env = Env::default();
    for (id, rec) in &snapshot.entities {
        if is_inherent_rec(snapshot, rec) || is_block_local_rec(snapshot, rec) {
            continue;
        }
        env.insert_def_in(&rec.name, rec.kind, *id, Some(&rec.file));
    }
    env
}

/// Inherent methods nested under `parent` (an `impl` or class), and associated
/// consts/statics so `Self::N` binds like `Self::foo()`. Empty when the item
/// is file-root: there is no receiver to bind against.
pub(crate) fn fill_self_methods_from_snapshot(
    env: &mut Env,
    snapshot: &Snapshot,
    parent: Option<EntityId>,
) {
    env.self_methods.clear();
    let Some(parent) = parent else {
        return;
    };
    env.self_methods = snapshot
        .entities
        .iter()
        .filter(|(_, rec)| rec.parent == Some(parent) && is_callable_member(rec.kind))
        .map(|(id, rec)| (rec.name.clone(), *id))
        .collect();
}

fn is_callable_member(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Fn | Kind::Const | Kind::Static | Kind::JsMethod | Kind::JsStaticMethod
    )
}

/// Items nested under `impl`/`trait`/`class` stay out of the file/crate maps.
/// Methods live in `self_methods` (`read()` is a free fn, `self.read()` is the
/// method). Associated consts/types would otherwise collide with a unique
/// crate-level `parse` the way nested fns and `#[cfg(test)] mod tests` did.
fn is_inherent_member(kind: Kind, parent_kind: Kind) -> bool {
    match parent_kind {
        Kind::Impl | Kind::Trait => matches!(
            kind,
            Kind::Fn | Kind::Const | Kind::TypeAlias | Kind::Static | Kind::Macro
        ),
        Kind::JsClass => matches!(
            kind,
            Kind::JsMethod
                | Kind::JsStaticMethod
                | Kind::JsGetter
                | Kind::JsSetter
                | Kind::JsField
                | Kind::JsStaticField
        ),
        _ => false,
    }
}

fn is_inherent_rec(snapshot: &Snapshot, rec: &EntityRecord) -> bool {
    rec.parent.is_some_and(|p| {
        snapshot
            .entities
            .get(&p)
            .is_some_and(|par| is_inherent_member(rec.kind, par.kind))
    })
}

fn is_inherent_raw(raw: &[RawEntity], i: usize) -> bool {
    raw[i]
        .parent_idx
        .is_some_and(|p| is_inherent_member(raw[i].kind, raw[p].kind))
}

/// A function body (and JS function/method body) can host nested items.
/// So can a `mod`: `#[cfg(test)] mod tests { fn parse() {} }` must not occupy
/// the file/crate maps (M3). Those names are in [`Env::nested_items`] while
/// that body — or a sibling in the same mod — is resolved.
fn hosts_block_items(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Fn
            | Kind::Mod
            | Kind::JsFunction
            | Kind::JsMethod
            | Kind::JsGetter
            | Kind::JsSetter
    )
}

fn is_block_local_rec(snapshot: &Snapshot, rec: &EntityRecord) -> bool {
    rec.parent.is_some_and(|p| {
        snapshot
            .entities
            .get(&p)
            .is_some_and(|par| hosts_block_items(par.kind))
    })
}

fn is_block_local_raw(raw: &[RawEntity], i: usize) -> bool {
    raw[i]
        .parent_idx
        .is_some_and(|p| hosts_block_items(raw[p].kind))
}

/// Associated types of the enclosing impl/trait are in scope for signatures
/// (`fn f() -> Item`) without occupying the file map. Methods stay out: a
/// bare `f()` is not the sibling method.
fn fill_associated_types_from_snapshot(env: &mut Env, snapshot: &Snapshot, id: EntityId) {
    let Some(rec) = snapshot.entities.get(&id) else {
        return;
    };
    let Some(parent) = rec.parent else {
        return;
    };
    let Some(prec) = snapshot.entities.get(&parent) else {
        return;
    };
    if !matches!(prec.kind, Kind::Impl | Kind::Trait) {
        return;
    }
    for (cid, crec) in &snapshot.entities {
        if crec.parent == Some(parent) && crec.kind == Kind::TypeAlias {
            env.insert_nested(&crec.name, crec.kind, *cid);
        }
    }
}

fn fill_associated_types_from_raw(env: &mut Env, raw: &[RawEntity], ids: &[EntityId], i: usize) {
    let Some(p) = raw[i].parent_idx else {
        return;
    };
    if !matches!(raw[p].kind, Kind::Impl | Kind::Trait) {
        return;
    }
    for (j, ch) in raw.iter().enumerate() {
        if ch.parent_idx == Some(p) && ch.kind == Kind::TypeAlias {
            env.insert_nested(&ch.name, ch.kind, ids[j]);
        }
    }
}

/// Nested `fn`/`struct`/… under `id` and under enclosing functions, inner last.
pub(crate) fn fill_nested_items_from_snapshot(env: &mut Env, snapshot: &Snapshot, id: EntityId) {
    env.nested_items.clear();
    fill_associated_types_from_snapshot(env, snapshot, id);
    let mut chain = vec![id];
    let mut walk = snapshot.entities.get(&id).and_then(|r| r.parent);
    while let Some(pid) = walk {
        let Some(prec) = snapshot.entities.get(&pid) else {
            break;
        };
        if !hosts_block_items(prec.kind) {
            break;
        }
        chain.push(pid);
        walk = prec.parent;
    }
    chain.reverse();
    for pid in chain {
        for (cid, crec) in &snapshot.entities {
            if crec.parent == Some(pid) && is_block_local_rec(snapshot, crec) {
                env.insert_nested(&crec.name, crec.kind, *cid);
            }
        }
    }
}

fn fill_nested_items_from_raw(env: &mut Env, raw: &[RawEntity], ids: &[EntityId], i: usize) {
    env.nested_items.clear();
    fill_associated_types_from_raw(env, raw, ids, i);
    let mut chain = vec![i];
    let mut walk = raw[i].parent_idx;
    while let Some(pi) = walk {
        if !hosts_block_items(raw[pi].kind) {
            break;
        }
        chain.push(pi);
        walk = raw[pi].parent_idx;
    }
    chain.reverse();
    for pi in chain {
        for (j, ch) in raw.iter().enumerate() {
            if ch.parent_idx == Some(pi) && is_block_local_raw(raw, j) {
                env.insert_nested(&ch.name, ch.kind, ids[j]);
            }
        }
    }
}

pub fn resolve(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> Result<Resolution> {
    Ok(canon::resolve_locals(item, src, lang, env))
}

pub fn to_bytes(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    resolution: &Resolution,
    children: &[(ByteRange, EntityId)],
    own_name: Option<EntityId>,
) -> Result<Bytes> {
    let extent = extract::byte_range(item);
    let name = own_name.and_then(|id| {
        item.child_by_field_name("name")
            .map(|n| (extract::byte_range(n), id))
    });
    bytes::bytes_from_span(src, extent, children, name, resolution, item)
}

pub fn canonicalize(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    res: &Resolution,
    children: &[(ByteRange, EntityId)],
    _env: &Env,
    lang: &dyn Lang,
) -> Result<Content> {
    canon::canonicalize(item, src, res, children, lang)
}

pub fn render(
    snapshot: &Snapshot,
    store: &dyn Store,
    _langs: &Langs,
    with_maps: bool,
) -> Result<Rendered> {
    render_impl::render(snapshot, store, with_maps)
}

pub fn render_entity(
    snapshot: &Snapshot,
    store: &dyn Store,
    id: EntityId,
    with_map: bool,
) -> Result<(Vec<u8>, Option<Vec<(ByteRange, IdentRef)>>)> {
    render_impl::render_entity(snapshot, store, id, with_map)
}

pub fn diff(
    store: &dyn Store,
    prev: &Snapshot,
    next: &Snapshot,
) -> Result<Vec<crate::delta::Delta>> {
    diff_impl::diff(store, prev, next)
}

/// Bytes-in → snapshot-out. Does not write the snapshot, set root/heads, or append an op.
/// `files` is the whole tree; `prev` lends ids only. Names resolve against what is parsed
/// here — never against `prev`, whose entities may be exactly what this edit deleted (a
/// reference kept bound to a gone id renders as `?`).
pub fn snapshot_files(
    store: &dyn Store,
    langs: &Langs,
    files: &BTreeMap<RelPath, Vec<u8>>,
    prev: Option<&Snapshot>,
    change: ChangeId,
) -> Result<Snapshot> {
    struct Parsed<'a> {
        path: RelPath,
        src: &'a [u8],
        tree: tree_sitter::Tree,
        raw: Vec<RawEntity>,
        lang: &'a dyn Lang,
        ids: Vec<EntityId>,
    }
    let mut parsed = Vec::new();
    let mut opaque = BTreeMap::new();
    let mut prev_ids = prev_ids(prev);
    for (path, src) in files {
        match langs.for_path(path) {
            Some(lang) => {
                let tree = parse(src, lang)?;
                let raw = extract(&tree, src, lang)?;
                let ids = assign_ids(&raw, path, &mut prev_ids, prev);
                parsed.push(Parsed {
                    path: path.clone(),
                    src,
                    tree,
                    raw,
                    lang,
                    ids,
                });
            }
            // Manifests, lockfiles, recordings: stored as the file tail with no
            // entities so `svc init` on this repo still renders a tree cargo can build.
            None => {
                opaque.insert(path.clone(), src.clone());
            }
        }
    }
    // Prev is for assign_ids. Seeding names from it keeps deleted same-file
    // defs in the env, so a remaining call binds to a missing id and render
    // prints `?` (claude 03:34: absorb after deleting resolve_entity_in).
    let mut env = Env::default();
    for p in &parsed {
        for (i, ent) in p.raw.iter().enumerate() {
            if is_inherent_raw(&p.raw, i) || is_block_local_raw(&p.raw, i) {
                continue;
            }
            env.insert_def_in(&ent.name, ent.kind, p.ids[i], Some(&p.path));
        }
    }
    let mut entities = BTreeMap::new();
    let mut file_recs = BTreeMap::new();
    for p in &parsed {
        let (ents, file) = materialize(
            p.src,
            p.path.clone(),
            p.lang,
            store,
            &p.tree,
            &p.raw,
            &p.ids,
            &env,
        )?;
        entities.extend(ents);
        file_recs.insert(p.path.clone(), file);
    }
    for (path, src) in opaque {
        file_recs.insert(path, FileRecord::from_tail(store, &src)?);
    }
    Ok(Snapshot {
        parents: Vec::new(),
        predecessors: Vec::new(),
        change,
        entities,
        files: file_recs,
        conflicts: Vec::new(),
        message: String::new(),
    })
}

pub fn ingest_file(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
) -> Result<Snapshot> {
    ingest_file_with_env(src, path, lang, store, change, &Env::default())
}

pub fn ingest_file_with_env(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
    extra: &Env,
) -> Result<Snapshot> {
    ingest_file_prev(src, path, lang, store, change, None, extra)
}

pub fn ingest_file_prev(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
    prev: Option<&Snapshot>,
    extra: &Env,
) -> Result<Snapshot> {
    let tree = parse(src, lang)?;
    let raw = extract(&tree, src, lang)?;
    let ids = assign_ids(&raw, &path, &mut prev_ids(prev), prev);
    let mut env = extra.clone();
    for (i, ent) in raw.iter().enumerate() {
        if is_inherent_raw(&raw, i) || is_block_local_raw(&raw, i) {
            continue;
        }
        env.insert_def_in(&ent.name, ent.kind, ids[i], Some(&path));
    }
    let (entities, file) = materialize(src, path.clone(), lang, store, &tree, &raw, &ids, &env)?;
    let mut files = BTreeMap::new();
    files.insert(path, file);
    Ok(Snapshot {
        parents: Vec::new(),
        predecessors: Vec::new(),
        change,
        entities,
        files,
        conflicts: Vec::new(),
        message: String::new(),
    })
}

fn materialize(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    tree: &tree_sitter::Tree,
    raw: &[RawEntity],
    ids: &[EntityId],
    env: &Env,
) -> Result<(BTreeMap<EntityId, EntityRecord>, FileRecord)> {
    let mut entities = BTreeMap::new();
    // Clone once per file: `Env.names` is Arc, so this is not O(n) in the snapshot.
    // Filling `self_methods` only when the caller left it empty — `edit_def` fills it
    // from the snapshot, and the fragment being parsed has no siblings (opus 03:05).
    let mut local_env = env.clone();
    local_env.current_file = Some(path.clone());
    let caller_supplied = !env.self_methods.is_empty();
    let mut sibs: std::collections::HashMap<usize, std::collections::HashMap<String, EntityId>> =
        std::collections::HashMap::new();
    if !caller_supplied {
        for (j, sib) in raw.iter().enumerate() {
            if let Some(p) = sib.parent_idx {
                if is_callable_member(sib.kind) {
                    sibs.entry(p).or_default().insert(sib.name.clone(), ids[j]);
                }
            }
        }
    }
    for (i, ent) in raw.iter().enumerate() {
        let node = extract::find_node(tree.root_node(), ent.item_range)
            .ok_or_else(|| Error::Parse(format!("no node for {}", ent.name)))?;
        if !caller_supplied {
            local_env.self_methods = ent
                .parent_idx
                .and_then(|p| sibs.get(&p))
                .cloned()
                .unwrap_or_default();
        }
        fill_nested_items_from_raw(&mut local_env, raw, ids, i);
        let res = resolve(node, src, lang, &local_env)?;
        let children: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].bytes_range, ids[c]))
            .collect();
        let own_name = ent.name_range.map(|r| (r, EntityId::SELF));
        let bytes = bytes::bytes_from_span(src, ent.bytes_range, &children, own_name, &res, node)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        let child_spans: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].item_range, ids[c]))
            .collect();
        let content = canonicalize(node, src, &res, &child_spans, &local_env, lang)?;
        let content_id = store.put_content(&content)?;
        let ordinal = raw
            .iter()
            .filter(|o| o.parent_idx == ent.parent_idx && o.item_range.start < ent.item_range.start)
            .count() as u32;
        entities.insert(
            ids[i],
            EntityRecord {
                name: ent.name.clone(),
                kind: ent.kind,
                parent: ent.parent_idx.map(|p| ids[p]),
                file: path.clone(),
                ordinal,
                content: content_id,
                bytes: bytes_id,
            },
        );
    }
    let roots: Vec<_> = raw
        .iter()
        .filter(|e| e.parent_idx.is_none())
        .cloned()
        .collect();
    let trailing = render_impl::trailing_for(src, &roots);
    Ok((entities, FileRecord::from_tail(store, &trailing)?))
}

/// Reuse ids from `prev` by SigKey: nested items match under their parent, file-level
/// items only within `file` (two files may each define `fn hex32`).
/// The previous snapshot's ids by signature, each list in id order: a re-ingested entity
/// keeps its id, and two same-signature entities take theirs in the order they had.
/// Built once per ingest; a lookup per raw entity instead of a scan of every record.
type PrevIds = BTreeMap<SigKey, std::collections::VecDeque<EntityId>>;

fn prev_ids(prev: Option<&Snapshot>) -> PrevIds {
    let mut by_sig = PrevIds::new();
    if let Some(prev) = prev {
        for (id, rec) in &prev.entities {
            by_sig.entry(rec.sig_key()).or_default().push_back(*id);
        }
    }
    by_sig
}

fn assign_ids(
    raw: &[RawEntity],
    file: &RelPath,
    prev: &mut PrevIds,
    snap: Option<&Snapshot>,
) -> Vec<EntityId> {
    let mut assigned: Vec<Option<EntityId>> = vec![None; raw.len()];
    let mut used = HashSet::new();
    for (i, ent) in raw.iter().enumerate() {
        let parent = match ent.parent_idx {
            Some(p) => match assigned[p] {
                Some(id) => Some(id),
                None => continue,
            },
            None => None,
        };
        let key = SigKey::new(parent, file, ent.kind, ent.name.clone());
        if let Some(id) = prev.get_mut(&key).and_then(|same| same.pop_front()) {
            assigned[i] = Some(id);
            used.insert(id);
        }
    }
    // A `use` line's name is its text. Rename of an imported fn (or a hand
    // edit of the path) changes that spelling, so SigKey misses and the line
    // used to mint a new id. Reuse an unused Opaque in this file whose text
    // still shares most of its prefix (`use crate::a::f` → `use crate::a::f2`).
    if let Some(snap) = snap {
        let leftover: Vec<(u32, EntityId, String)> = snap
            .entities
            .iter()
            .filter(|(id, rec)| rec.file == *file && rec.kind == Kind::Opaque && !used.contains(id))
            .map(|(id, rec)| (rec.ordinal, *id, rec.name.clone()))
            .collect();
        for (i, ent) in raw.iter().enumerate() {
            if assigned[i].is_some() || ent.kind != Kind::Opaque {
                continue;
            }
            let mut best: Option<(usize, u32, EntityId)> = None;
            for (ord, id, name) in &leftover {
                if used.contains(id) {
                    continue;
                }
                let n = lcp(&ent.name, name);
                if n * 2 < ent.name.len().min(name.len()) {
                    continue;
                }
                match best {
                    Some((bn, bord, _)) if (n, std::cmp::Reverse(*ord)) < (bn, std::cmp::Reverse(bord)) => {}
                    _ => best = Some((n, *ord, *id)),
                }
            }
            if let Some((_, _, id)) = best {
                assigned[i] = Some(id);
                used.insert(id);
            }
        }
    }
    assigned
        .into_iter()
        .map(|id| id.unwrap_or_else(EntityId::new))
        .collect()
}

fn lcp(a: &str, b: &str) -> usize {
    a.bytes()
        .zip(b.bytes())
        .take_while(|(x, y)| x == y)
        .count()
}

crates/svc-core/src/engine/ops.rs.Text:
use std::collections::{BTreeMap, BTreeSet};

use crate::content::{Bytes, Chunk, Content, IdentRef, Token};
use crate::delta::{Delta, ObservedClass};
use crate::entity::{EntityRecord, Kind, SigKey};
use crate::error::{Error, Result};
use crate::ids::{ByteRange, EntityId, RelPath, resolve_spec};
use crate::lang::{Lang, Langs};
use crate::op::Intent;
use crate::snapshot::Snapshot;
use crate::store::Store;

use super::diff_impl::lang_for_ext;
use super::{
    classify_entity, env_from_snapshot, fill_self_methods_from_snapshot, ingest_file_prev,
    ingest_file_with_env, parse, render, render_entity,
};

pub fn lookup_name(snap: &Snapshot, name: &str) -> Result<EntityId> {
    let hits: Vec<_> = snap
        .entities
        .iter()
        .filter(|(_, r)| r.name == name)
        .map(|(id, _)| *id)
        .collect();
    match hits.len() {
        1 => Ok(hits[0]),
        0 => Err(Error::NotFound(name.into())),
        _ => Err(Error::Other(format!("ambiguous name {name}"))),
    }
}

pub fn lookup(snap: &Snapshot, spec: &str) -> Result<EntityId> {
    if let Ok(id) = lookup_name(snap, spec) {
        return Ok(id);
    }
    match resolve_spec(snap.entities.keys().copied(), |id| id.matches_spec(spec)) {
        Ok(id) => Ok(id),
        Err(hits) if hits.is_empty() => Err(Error::NotFound(spec.into())),
        Err(_) => Err(Error::Other(format!("ambiguous entity {spec}"))),
    }
}

/// Attribute-only: referrers keep `Chunk::Name` holes. No rehash.
pub fn rename(store: &dyn Store, snap: &Snapshot, id: EntityId, new: &str) -> Result<Snapshot> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let has_decl = store
        .get_bytes_blob(rec.bytes)?
        .chunks()
        .iter()
        .any(|c| matches!(c, Chunk::Name(e) if *e == EntityId::SELF));
    if !has_decl {
        return Err(Error::Other(format!(
            "rename cannot rewrite {}; the declaration has no name spelling",
            rec.name
        )));
    }
    let mut next = snap.clone();
    next.rename(id, new)?;
    Ok(next)
}

pub fn relocate(snap: &Snapshot, store: &dyn Store, id: EntityId, file: RelPath, ordinal: u32) -> Result<Snapshot> {
    let from = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .file
        .clone();
    let mut next = snap.clone();
    // Render iterates `snapshot.files`, not entities. A path that never had a
    // FileRecord would swallow the item on disk even though the entity moved.
    next.ensure_file(file.clone());
    next.make_room_at_root(&file, ordinal, id);
    next.set_file(id, file.clone(), ordinal)?;
    normalize_root_separators(store, &mut next, &file)?;
    if from != file {
        normalize_root_separators(store, &mut next, &from)?;
    }
    Ok(next)
}

pub fn move_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: Option<u32>,
) -> Result<Snapshot> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    if let Some(p) = new_parent {
        if p == id || subtree(snap, id).contains(&p) {
            return Err(Error::Other("move would create a cycle".into()));
        }
        snap.entities.get(&p).ok_or(Error::NoSuchEntity(p))?;
    }
    let old_parent = rec.parent;
    let mut next = snap.clone();
    if let (None, Some(o)) = (new_parent, ordinal) {
        next.make_room_at_root(&rec.file, o, id);
    }
    next.reparent(id, new_parent, ordinal)?;
    if let Some(p) = new_parent {
        let file = next.entities[&p].file.clone();
        next.set_file(id, file, ordinal.unwrap_or(rec.ordinal))?;
    }
    if old_parent != new_parent {
        reindent_subtree(store, &mut next, id, new_parent)?;
    }
    if old_parent == new_parent {
        if let Some(p) = new_parent {
            let mut kids = child_ids_of(store, &next, p)?;
            kids.retain(|c| *c != id);
            let at = ordinal.unwrap_or(kids.len() as u32) as usize;
            kids.insert(at.min(kids.len()), id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
        if new_parent.is_none() {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
        return Ok(next);
    }
    if let Some(p) = old_parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    if let Some(p) = new_parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = ordinal.unwrap_or(kids.len() as u32) as usize;
        kids.insert(at.min(kids.len()), id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    reresolve_subtree(store, langs, &mut next, id)?;
    if old_parent.is_none() || new_parent.is_none() {
        let file = next.entities[&id].file.clone();
        normalize_root_separators(store, &mut next, &file)?;
        if rec.file != file {
            normalize_root_separators(store, &mut next, &rec.file)?;
        }
    }
    Ok(next)
}

pub fn extract_hoist(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
    ordinal: u32,
) -> Result<Snapshot> {
    move_def(store, langs, snap, id, new_parent, Some(ordinal))
}

/// Parse the destination file so inherited generics / outer locals match the
/// new parent, then copy the subtree's content and bytes back. Reorder under
/// the same parent does not call this — the env did not change.
fn reresolve_subtree(
    store: &dyn Store,
    langs: &Langs,
    snap: &mut Snapshot,
    id: EntityId,
) -> Result<()> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let rendered = render(snap, store, langs, false)?;
    let src = rendered
        .files
        .get(&rec.file)
        .ok_or_else(|| Error::Other(format!("re-resolve missing file {}", rec.file)))?;
    let env = env_from_snapshot(snap);
    let part = ingest_file_prev(
        src,
        rec.file.clone(),
        lang,
        store,
        snap.change,
        Some(snap),
        &env,
    )?;
    for eid in subtree(snap, id) {
        let (name, kind, parent) = {
            let rec = snap.entities.get(&eid).ok_or(Error::NoSuchEntity(eid))?;
            (rec.name.clone(), rec.kind, rec.parent)
        };
        let fresh = part
            .entities
            .get(&eid)
            .or_else(|| {
                part.entities
                    .values()
                    .find(|r| r.name == name && r.kind == kind && r.parent == parent)
            })
            .ok_or_else(|| Error::Other(format!("re-resolve lost {name}")))?;
        let content = fresh.content;
        let bytes = fresh.bytes;
        if let Some(dest) = snap.entities.get_mut(&eid) {
            dest.content = content;
            dest.bytes = bytes;
        }
    }
    Ok(())
}

pub fn delete(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Snapshot> {
    let tree = subtree(snap, id);
    let mut outside = Vec::new();
    for d in &tree {
        outside.extend(
            referrers(snap, store, *d)?
                .into_iter()
                .filter(|r| !tree.contains(r)),
        );
    }
    outside.sort();
    outside.dedup();
    if !outside.is_empty() {
        let named: Vec<String> = outside
            .iter()
            .take(5)
            .map(|r| match snap.entities.get(r) {
                Some(rec) => format!("{} ({}⟨{}⟩)", rec.name, rec.file, r.short()),
                None => format!("⟨{}⟩", r.short()),
            })
            .collect();
        let more = if outside.len() > 5 {
            format!(", and {} more", outside.len() - 5)
        } else {
            String::new()
        };
        return Err(Error::Other(format!(
            "delete refused: still referenced by {}{more}",
            named.join(", ")
        )));
    }
    let parent = snap.entities.get(&id).and_then(|r| r.parent);
    let mut next = snap.clone();
    for d in tree {
        next.entities.remove(&d);
    }
    if let Some(p) = parent {
        if next.entities.contains_key(&p) {
            let mut kids = child_ids_of(store, snap, p)?;
            kids.retain(|c| *c != id);
            apply_child_holes(store, &mut next, p, &kids)?;
        }
    }
    Ok(next)
}

pub fn inline(store: &dyn Store, langs: &Langs, snap: &Snapshot, id: EntityId) -> Result<Snapshot> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    // A `use` line that imports the callee names it too; it is not a call site, and
    // after the splice it would import something that no longer exists.
    let (imports, calls): (Vec<EntityId>, Vec<EntityId>) = name_use_sites(snap, store, id)?
        .into_iter()
        .partition(|s| snap.entities[s].kind == Kind::Opaque);
    if let Some(import) = imports.first() {
        let i = &snap.entities[import];
        return Err(Error::Other(format!(
            "inline refused: `{}` is imported by `{}` in {}; drop it from that import first",
            rec.name,
            i.name.lines().next().unwrap_or(&i.name),
            i.file
        )));
    }
    if calls.len() != 1 {
        return Err(Error::Other(format!(
            "inline requires a single use; found {}",
            calls.len()
        )));
    }
    let referrer = calls[0];
    if subtree(snap, referrer).contains(&id) {
        return Err(Error::Other(
            "inline cannot target an item still nested in the call site; extract first".into(),
        ));
    }
    let replacement = inlined_call_text(store, langs, snap, id, referrer)?;
    let (next, _) = edit_def(store, langs, snap, referrer, &replacement)?;
    delete(&next, store, id)
}

/// `Chunk::Name(id)` sites, including recursive uses inside `id` itself.
/// The declaration hole is `Name(SELF)`, not `Name(id)`.
fn name_use_sites(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut sites = Vec::new();
    for (oid, rec) in &snap.entities {
        let n = store
            .get_bytes_blob(rec.bytes)?
            .chunks()
            .iter()
            .filter(|c| {
                matches!(
                    c,
                    Chunk::Name(e) if *e == id
                ) || matches!(
                    c,
                    Chunk::ShorthandName { id: e, .. } if *e == id
                )
            })
            .count();
        for _ in 0..n {
            sites.push(*oid);
        }
    }
    Ok(sites)
}

fn inlined_call_text(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    referrer: EntityId,
) -> Result<Vec<u8>> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let (callee, _) = render_entity(snap, store, id, false)?;
    let (params, body) = callee_params_and_body(lang, &callee)?;
    let (caller, map) = render_entity(snap, store, referrer, true)?;
    let ranges: Vec<ByteRange> = map
        .as_deref()
        .unwrap_or(&[])
        .iter()
        .filter_map(|(r, ident)| match ident {
            IdentRef::Entity(e) if *e == id => Some(*r),
            _ => None,
        })
        .collect();
    match ranges.as_slice() {
        [range] => {
            let name_end = range.end as usize;
            if name_end > caller.len() || (range.start as usize) > name_end {
                return Err(Error::Other("inline call range is out of bounds".into()));
            }
            let (call_end, args) = extend_call(&caller, name_end)?;
            if args.len() != params.len() {
                return Err(Error::Other(format!(
                    "inline expected {} argument(s), found {}",
                    params.len(),
                    args.len()
                )));
            }
            let mut block = bind_and_body(&params, &args, &body);
            if rust_postfix(&caller, call_end) {
                if lang.name() != "rust" {
                    return Err(Error::Other(
                        "inline of an expression-position call is only supported in rust".into(),
                    ));
                }
                block = format!("({block})");
            }
            let start = range.start as usize;
            let mut out = Vec::with_capacity(caller.len() + block.len());
            out.extend_from_slice(&caller[..start]);
            out.extend_from_slice(block.as_bytes());
            out.extend_from_slice(&caller[call_end..]);
            Ok(out)
        }
        _ => Err(Error::Other(format!(
            "inline needs one call name in the unique user; found {}",
            ranges.len()
        ))),
    }
}

fn callee_params_and_body(lang: &dyn Lang, src: &[u8]) -> Result<(Vec<String>, String)> {
    let tree = parse(src, lang)?;
    let item = entity_item_node(tree.root_node(), lang)
        .ok_or_else(|| Error::Other("inline target does not parse as a language item".into()))?;
    let rule = lang
        .entity_kinds()
        .iter()
        .find(|r| r.node_kind == item.kind())
        .ok_or_else(|| Error::Other("inline target is not a language item".into()))?;
    let body_field = rule.body_field.ok_or_else(|| {
        Error::Other("inline needs an item with a body (not a type or signature)".into())
    })?;
    let body = item
        .child_by_field_name(body_field)
        .ok_or_else(|| Error::Other("inline target has no body".into()))?;
    let params = match item.child_by_field_name("parameters") {
        Some(n) => param_names(n, src)?,
        None => Vec::new(),
    };
    Ok((params, node_src(src, body)))
}

fn entity_item_node<'a>(
    node: tree_sitter::Node<'a>,
    lang: &dyn Lang,
) -> Option<tree_sitter::Node<'a>> {
    if lang
        .entity_kinds()
        .iter()
        .any(|r| r.node_kind == node.kind())
    {
        return Some(node);
    }
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        if let Some(hit) = entity_item_node(ch, lang) {
            return Some(hit);
        }
    }
    None
}

fn param_names(params: tree_sitter::Node<'_>, src: &[u8]) -> Result<Vec<String>> {
    let mut names = Vec::new();
    let mut c = params.walk();
    for ch in params.named_children(&mut c) {
        match ch.kind() {
            "self_parameter" => {
                return Err(Error::Other(
                    "inline of a method (self) is not supported".into(),
                ));
            }
            "identifier" => names.push(node_src(src, ch)),
            "parameter" | "required_parameter" | "optional_parameter" | "rest_parameter"
            | "assignment_pattern" => {
                let pat = ch
                    .child_by_field_name("pattern")
                    .or_else(|| ch.child_by_field_name("name"))
                    .unwrap_or(ch);
                match simple_pat_name(pat, src) {
                    Some(n) => names.push(n),
                    None => {
                        return Err(Error::Other(
                            "inline needs simple identifier parameters".into(),
                        ));
                    }
                }
            }
            _ => {}
        }
    }
    Ok(names)
}

fn simple_pat_name(node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String> {
    match node.kind() {
        "identifier" => Some(node_src(src, node)),
        "mut_pattern" => {
            let mut c = node.walk();
            node.named_children(&mut c)
                .find(|ch| ch.kind() == "identifier")
                .map(|id| node_src(src, id))
        }
        _ => None,
    }
}

fn node_src(src: &[u8], n: tree_sitter::Node<'_>) -> String {
    let a = n.start_byte().min(src.len());
    let b = n.end_byte().min(src.len()).max(a);
    String::from_utf8_lossy(&src[a..b]).into_owned()
}

fn extend_call(src: &[u8], name_end: usize) -> Result<(usize, Vec<String>)> {
    let mut i = name_end;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    if i >= src.len() || src[i] != b'(' {
        return Err(Error::Other("inline needs a call site".into()));
    }
    let close = matching_paren(src, i)?;
    Ok((close + 1, split_args(&src[i + 1..close])))
}

fn matching_paren(src: &[u8], open: usize) -> Result<usize> {
    let mut i = open;
    let mut depth = 0i32;
    while i < src.len() {
        let b = src[i];
        if b == b'/' && i + 1 < src.len() {
            if src[i + 1] == b'/' {
                i += 2;
                while i < src.len() && src[i] != b'\n' {
                    i += 1;
                }
                continue;
            }
            if src[i + 1] == b'*' {
                i += 2;
                while i + 1 < src.len() && !(src[i] == b'*' && src[i + 1] == b'/') {
                    i += 1;
                }
                i = i.saturating_add(2);
                continue;
            }
        }
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < src.len() {
                if src[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if src[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        if b == b'(' {
            depth += 1;
        } else if b == b')' {
            depth -= 1;
            if depth == 0 {
                return Ok(i);
            }
        }
        i += 1;
    }
    Err(Error::Other("inline call is unclosed".into()))
}

fn split_args(inner: &[u8]) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth = 0i32;
    let mut i = 0usize;
    while i < inner.len() {
        let b = inner[i];
        if b == b'"' || b == b'\'' {
            let quote = b;
            i += 1;
            while i < inner.len() {
                if inner[i] == b'\\' {
                    i = i.saturating_add(2);
                    continue;
                }
                if inner[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            continue;
        }
        match b {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth = depth.saturating_sub(1),
            b',' if depth == 0 => {
                push_arg(&mut out, &inner[start..i]);
                start = i + 1;
            }
            _ => {}
        }
        i += 1;
    }
    push_arg(&mut out, &inner[start..]);
    out
}

fn push_arg(out: &mut Vec<String>, piece: &[u8]) {
    let s = String::from_utf8_lossy(piece).trim().to_string();
    if !s.is_empty() {
        out.push(s);
    }
}

fn bind_and_body(params: &[String], args: &[String], body: &str) -> String {
    if params.is_empty() {
        return body.to_string();
    }
    let mut s = String::from("{\n");
    for (p, a) in params.iter().zip(args) {
        s.push_str("    let ");
        s.push_str(p);
        s.push_str(" = ");
        s.push_str(a);
        s.push_str(";\n");
    }
    s.push_str(body);
    if !body.ends_with('\n') {
        s.push('\n');
    }
    s.push('}');
    s
}

fn rust_postfix(src: &[u8], after_call: usize) -> bool {
    let mut i = after_call;
    while i < src.len() && src[i].is_ascii_whitespace() {
        i += 1;
    }
    i < src.len() && matches!(src[i], b'?' | b'.')
}

pub fn edit_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<(Snapshot, ObservedClass)> {
    let rec = snap
        .entities
        .get(&id)
        .ok_or(Error::NoSuchEntity(id))?
        .clone();
    let lang = langs
        .for_path(&rec.file)
        .ok_or_else(|| Error::NoLanguage(rec.file.clone()))?;
    let definition = item_text(store, snap, id, definition)?;
    let (root_old, part) = ingest_item_tree(
        "edit-def",
        store,
        snap,
        &rec.file,
        lang,
        rec.parent,
        &definition,
    )?;
    let mapped = remap_tree(store, part.entities, root_old, id, Some(snap))?;
    let new_rec = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("edit-def lost the root item".into()))?;
    if new_rec.name != rec.name {
        return Err(Error::Other(format!(
            "edit-def cannot rename {} to {}; use svc rename",
            rec.name, new_rec.name
        )));
    }
    if new_rec.kind != rec.kind {
        return Err(Error::Other(format!(
            "edit-def cannot change {} from {:?} to {:?}; delete and add-def instead",
            rec.name, rec.kind, new_rec.kind
        )));
    }
    let new_content = new_rec.content;
    let new_bytes = new_rec.bytes;
    let mut next = snap.clone();
    for cid in subtree(snap, id) {
        if cid != id {
            next.entities.remove(&cid);
        }
    }
    if let Some(dest) = next.entities.get_mut(&id) {
        dest.content = new_content;
        dest.bytes = new_bytes;
    }
    for (cid, mut child) in mapped {
        if cid == id {
            continue;
        }
        child.file = rec.file.clone();
        next.insert(cid, child)?;
    }
    let class = classify_entity(store, snap, &next, id)?;
    Ok((next, class))
}

pub fn add_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    ordinal: u32,
    definition: &[u8],
    intent: Intent,
) -> Result<Snapshot> {
    add_def_at(
        store, langs, snap, id, parent, None, ordinal, definition, intent,
    )
}

/// Parent's file, else the first tracked source file. An explicit `file` wins.
pub fn resolve_add_def_file(
    snap: &Snapshot,
    langs: &Langs,
    parent: Option<EntityId>,
    file: Option<RelPath>,
) -> Result<RelPath> {
    if let Some(file) = file {
        return Ok(file);
    }
    match parent {
        Some(p) => Ok(snap
            .entities
            .get(&p)
            .ok_or(Error::NoSuchEntity(p))?
            .file
            .clone()),
        None => Ok(snap
            .files
            .keys()
            .find(|p| langs.for_path(p).is_some())
            .cloned()
            .ok_or_else(|| Error::Other("no tracked source file to add into".into()))?),
    }
}

pub fn add_def_at(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    parent: Option<EntityId>,
    file: Option<RelPath>,
    ordinal: u32,
    definition: &[u8],
    _intent: Intent,
) -> Result<Snapshot> {
    let file = resolve_add_def_file(snap, langs, parent, file)?;
    let lang = langs
        .for_path(&file)
        .ok_or_else(|| Error::NoLanguage(file.clone()))?;
    let indent = parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    let definition = add_def_text(parent, &indent, definition);
    let (root_old, part) =
        ingest_item_tree("add-def", store, snap, &file, lang, parent, &definition)?;
    let mapped = remap_tree(store, part.entities, root_old, id, None)?;
    let mut next = snap.clone();
    next.ensure_file(file.clone());
    let mut root = mapped
        .get(&id)
        .cloned()
        .ok_or_else(|| Error::Other("add-def lost the root item".into()))?;
    root.parent = parent;
    root.file = file.clone();
    root.ordinal = ordinal;
    if parent.is_none() {
        next.make_room_at_root(&file, ordinal, id);
    }
    next.insert(id, root)?;
    for (cid, mut rec) in mapped {
        if cid == id {
            continue;
        }
        rec.file = file.clone();
        next.insert(cid, rec)?;
    }
    if let Some(p) = parent {
        let mut kids = child_ids_of(store, &next, p)?;
        kids.retain(|c| *c != id);
        let at = (ordinal as usize).min(kids.len());
        kids.insert(at, id);
        apply_child_holes(store, &mut next, p, &kids)?;
    }
    Ok(next)
}

pub fn classify_def(
    store: &dyn Store,
    langs: &Langs,
    snap: &Snapshot,
    id: EntityId,
    definition: &[u8],
) -> Result<ObservedClass> {
    let (_, class) = edit_def(store, langs, snap, id, definition)?;
    Ok(class)
}

pub fn show(store: &dyn Store, snap: &Snapshot, id: EntityId) -> Result<String> {
    let rec = snap.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let content = store.get_content(rec.content)?;
    Ok(format_tokens(snap, &content.tokens, &rec.name))
}

pub fn format_tokens(snap: &Snapshot, tokens: &[Token], self_name: &str) -> String {
    let mut out = String::new();
    for t in tokens {
        match t {
            Token::Punct(p) | Token::Kw(p) | Token::Lit(p) => out.push_str(p),
            Token::Binder(s, _) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Local(s, _)) => out.push_str(&format!("${}", s.0)),
            Token::Ident(IdentRef::Free(n)) => out.push_str(n),
            Token::Ident(IdentRef::Entity(eid)) if *eid == EntityId::SELF => {
                out.push_str(self_name)
            }
            Token::Ident(IdentRef::Entity(eid)) | Token::Child(eid) => {
                let name = snap
                    .entities
                    .get(eid)
                    .map(|e| e.name.as_str())
                    .unwrap_or("?");
                out.push_str(&format!("#{name}⟨{}⟩", eid.short()));
            }
        }
        out.push(' ');
    }
    out
}

/// Layout: alpha/docs-only edits, commutative relocations, and file deltas of source
/// files (their entities are counted on their own; a tail is trivia, or whitespace).
/// Semantic: everything else, including any change to a file svc has no language for.
pub fn status_report(store: &dyn Store, prev: &Snapshot, next: &Snapshot) -> Result<StatusReport> {
    let deltas = super::diff(store, prev, next)?;
    let is_source = |p: &RelPath| lang_for_ext(p.extension()).is_some();
    let mut layout = 0usize;
    let mut semantic = 0usize;
    let mut rebound = 0usize;
    for d in &deltas {
        match d {
            Delta::Rebound(_, _) => rebound += 1,
            Delta::Edited(_, ObservedClass::Alpha | ObservedClass::DocsOnly)
            | Delta::Relocated { .. } => layout += 1,
            Delta::FileAdded(p) | Delta::FileRemoved(p) if is_source(p) => layout += 1,
            Delta::FileTail { path, whitespace_only } if *whitespace_only || is_source(path) => {
                layout += 1
            }
            _ => semantic += 1,
        }
    }
    Ok(StatusReport {
        entities: next.entities.len(),
        deltas,
        layout,
        semantic,
        rebound,
    })
}

#[derive(Clone, Debug)]
pub struct StatusReport {
    pub entities: usize,
    pub deltas: Vec<Delta>,
    pub layout: usize,
    pub semantic: usize,
    /// Same bytes, different content — named, not counted as an edit.
    pub rebound: usize,
}

impl StatusReport {
    pub fn summary(&self) -> String {
        let rebound = if self.rebound == 0 {
            String::new()
        } else if self.rebound == 1 {
            "; 1 rebound, text unchanged".into()
        } else {
            format!("; {} rebound, text unchanged", self.rebound)
        };
        if self.deltas.is_empty() {
            format!("{} entities, 0 changes", self.entities)
        } else if self.semantic == 0 && self.layout == 0 {
            format!(
                "{} rebound, text unchanged ({} entities)",
                self.rebound, self.entities
            )
        } else if self.semantic == 0 {
            format!("no semantic changes; {} layout{rebound}", self.layout)
        } else {
            format!(
                "{} semantic; {} layout ({} entities){rebound}",
                self.semantic, self.layout, self.entities
            )
        }
    }
}

/// Entities whose content or bytes *name* `id`. Child holes are containment,
/// not uses — counting them made every nested delete refuse.
pub fn referrers(snap: &Snapshot, store: &dyn Store, id: EntityId) -> Result<Vec<EntityId>> {
    let mut out = Vec::new();
    for (oid, rec) in &snap.entities {
        if *oid == id {
            continue;
        }
        let in_content = store
            .get_content(rec.content)?
            .tokens
            .iter()
            .any(|t| match t {
                Token::Ident(IdentRef::Entity(e)) => *e == id,
                _ => false,
            });
        let in_bytes = || -> Result<bool> {
            Ok(store
                .get_bytes_blob(rec.bytes)?
                .chunks()
                .iter()
                .any(|c| match c {
                    Chunk::Name(e) => *e == id,
                    Chunk::ShorthandName { id: e, .. } => *e == id,
                    _ => false,
                }))
        };
        if in_content || in_bytes()? {
            out.push(*oid);
        }
    }
    Ok(out)
}

fn child_ids_in_chunks(chunks: &[Chunk]) -> Vec<EntityId> {
    chunks
        .iter()
        .filter_map(|c| match c {
            Chunk::Child(id) => Some(*id),
            _ => None,
        })
        .collect()
}

fn child_ids_of(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Result<Vec<EntityId>> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?;
    Ok(child_ids_in_chunks(
        store.get_bytes_blob(rec.bytes)?.chunks(),
    ))
}

fn apply_child_holes(
    store: &dyn Store,
    snap: &mut Snapshot,
    parent: EntityId,
    want: &[EntityId],
) -> Result<()> {
    let rec = snap
        .entities
        .get(&parent)
        .ok_or(Error::NoSuchEntity(parent))?
        .clone();
    let bytes = store.get_bytes_blob(rec.bytes)?;
    let content = store.get_content(rec.content)?;
    let new_bytes = rewrite_bytes_children(&bytes, want)?;
    let new_content = Content {
        tokens: rewrite_content_children(content.tokens, want),
    };
    let bytes_id = store.put_bytes_blob(&new_bytes)?;
    let content_id = store.put_content(&new_content)?;
    let rec = snap.entities.get_mut(&parent).unwrap();
    rec.bytes = bytes_id;
    rec.content = content_id;
    Ok(())
}

fn rewrite_bytes_children(bytes: &Bytes, want: &[EntityId]) -> Result<Bytes> {
    let have = child_ids_in_chunks(bytes.chunks());
    if have == want {
        return Ok(Bytes::new(
            bytes.src().to_vec(),
            bytes.chunks().to_vec(),
            bytes.local_ranges().to_vec(),
        )?);
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut src = bytes.src().to_vec();
    let mut chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .cloned()
        .filter(|c| match c {
            Chunk::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if child_ids_in_chunks(&chunks).contains(id) {
            continue;
        }
        chunks = insert_child_chunk(&mut src, chunks, *id, i);
    }
    let have = child_ids_in_chunks(&chunks);
    if have != want {
        let mut iter = want.iter();
        for c in &mut chunks {
            if let Chunk::Child(id) = c
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    Bytes::new(src, chunks, bytes.local_ranges().to_vec())
}

fn insert_child_chunk(
    src: &mut Vec<u8>,
    mut chunks: Vec<Chunk>,
    id: EntityId,
    ordinal: usize,
) -> Vec<Chunk> {
    let positions: Vec<usize> = chunks
        .iter()
        .enumerate()
        .filter_map(|(i, c)| matches!(c, Chunk::Child(_)).then_some(i))
        .collect();
    let insert_at = if ordinal < positions.len() {
        positions[ordinal]
    } else if let Some(&last) = positions.last() {
        last + 1
    } else {
        split_close_brace(src, &mut chunks)
    };
    // A member's bytes end at its last token; whatever follows must begin on a new
    // line. The next sibling carries its own leading newline, and so does the parent's
    // closing text in every rendered file — only a bare `}` (split_close_brace) or a
    // literal that starts mid-line needs one added here.
    let next_starts_on_new_line = match chunks.get(insert_at) {
        Some(Chunk::Child(_)) => true,
        Some(Chunk::Literal(r)) => src.get(r.start as usize) == Some(&b'\n'),
        Some(Chunk::Name(_) | Chunk::ShorthandName { .. }) | None => false,
    };
    chunks.insert(insert_at, Chunk::Child(id));
    if !next_starts_on_new_line {
        let extra_start = src.len() as u32;
        src.extend_from_slice(b"\n");
        let extra = ByteRange {
            start: extra_start,
            end: src.len() as u32,
        };
        chunks.insert(insert_at + 1, Chunk::Literal(extra));
    }
    chunks
}

fn split_close_brace(src: &[u8], chunks: &mut Vec<Chunk>) -> usize {
    for i in (0..chunks.len()).rev() {
        let Chunk::Literal(r) = chunks[i] else {
            continue;
        };
        let slice = &src[r.start as usize..r.end as usize];
        let Some(rel) = slice.iter().rposition(|&b| b == b'}') else {
            continue;
        };
        let brace = r.start + rel as u32;
        chunks.remove(i);
        let mut at = i;
        if brace > r.start {
            chunks.insert(
                at,
                Chunk::Literal(ByteRange {
                    start: r.start,
                    end: brace,
                }),
            );
            at += 1;
        }
        chunks.insert(
            at,
            Chunk::Literal(ByteRange {
                start: brace,
                end: r.end,
            }),
        );
        return at;
    }
    chunks.len()
}

fn rewrite_content_children(tokens: Vec<Token>, want: &[EntityId]) -> Vec<Token> {
    let content_kids = |tokens: &[Token]| -> Vec<EntityId> {
        tokens
            .iter()
            .filter_map(|t| match t {
                Token::Child(id) => Some(*id),
                _ => None,
            })
            .collect()
    };
    if content_kids(&tokens) == want {
        return tokens;
    }
    let want_set: BTreeSet<EntityId> = want.iter().copied().collect();
    let mut tokens: Vec<Token> = tokens
        .into_iter()
        .filter(|t| match t {
            Token::Child(id) => want_set.contains(id),
            _ => true,
        })
        .collect();
    for (i, id) in want.iter().enumerate() {
        if content_kids(&tokens).contains(id) {
            continue;
        }
        let positions: Vec<usize> = tokens
            .iter()
            .enumerate()
            .filter_map(|(j, t)| matches!(t, Token::Child(_)).then_some(j))
            .collect();
        let at = if i < positions.len() {
            positions[i]
        } else if let Some(&last) = positions.last() {
            last + 1
        } else {
            tokens
                .iter()
                .rposition(|t| matches!(t, Token::Punct(p) if p.as_ref() == "}"))
                .unwrap_or(tokens.len())
        };
        tokens.insert(at, Token::Child(*id));
    }
    if content_kids(&tokens) != want {
        let mut iter = want.iter();
        for t in &mut tokens {
            if let Token::Child(id) = t
                && let Some(next) = iter.next()
            {
                *id = *next;
            }
        }
    }
    tokens
}

fn subtree(snap: &Snapshot, id: EntityId) -> BTreeSet<EntityId> {
    let mut out = BTreeSet::from([id]);
    let mut grow = true;
    while grow {
        grow = false;
        for (cid, rec) in &snap.entities {
            if let Some(p) = rec.parent
                && out.contains(&p)
                && out.insert(*cid)
            {
                grow = true;
            }
        }
    }
    out
}

pub fn commit_snapshot(store: &dyn Store, snap: &Snapshot) -> Result<crate::ids::SnapshotId> {
    let id = store.put_snapshot(snap)?;
    store.set_root(id)?;
    store.set_head(snap.change, id)?;
    Ok(id)
}

pub fn rust_langs() -> Langs {
    Langs::new(vec![Box::new(crate::RustLang)])
}

/// Same nested-child keep as `edit_def`. Returns the new snapshot plus the
/// edited root's hashes so O3 can assert callee holes without walking entities.
pub fn redefine(
    store: &dyn Store,
    langs: &Langs,
    snapshot: &Snapshot,
    id: EntityId,
    text: &[u8],
) -> Result<(Snapshot, crate::ids::ContentId, crate::ids::BytesId)> {
    let (next, _) = edit_def(store, langs, snapshot, id, text)?;
    let rec = next.entities.get(&id).ok_or(Error::NoSuchEntity(id))?;
    let hashes = (rec.content, rec.bytes);
    Ok((next, hashes.0, hashes.1))
}

/// The one item a verb body must be: parses without error nodes, exactly one root
/// entity. Ingest itself is lenient (a checked-in file may be mid-edit); the typed
/// write path is not.
/// Parse and ingest one definition. Under a parent whose members do not parse on their
/// own (a JS class), the text is wrapped in the language's member shell and the member,
/// not the shell, is returned as the root.
fn ingest_item_tree(
    verb: &str,
    store: &dyn Store,
    snap: &Snapshot,
    file: &RelPath,
    lang: &dyn crate::lang::Lang,
    parent: Option<EntityId>,
    text: &[u8],
) -> Result<(EntityId, Snapshot)> {
    let parent_kind = parent.and_then(|p| snap.entities.get(&p)).map(|r| r.kind);
    let shell = parent_kind.and_then(|k| lang.member_shell(k));
    let wrapped: Vec<u8> = match shell {
        Some((open, close)) => [open.as_bytes(), text, close.as_bytes()].concat(),
        None => text.to_vec(),
    };
    if super::parse(&wrapped, lang)?.root_node().has_error() {
        return Err(Error::Parse(format!(
            "{verb} definition does not parse as {}",
            lang.name()
        )));
    }
    let mut env = env_from_snapshot(snap);
    fill_self_methods_from_snapshot(&mut env, snap, parent);
    let mut part = ingest_file_with_env(&wrapped, file.clone(), lang, store, snap.change, &env)?;
    let roots: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent.is_none())
        .map(|(id, _)| *id)
        .collect();
    let [root] = roots.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must parse to exactly one item"
        )));
    };
    let root = *root;
    if shell.is_none() {
        return Ok((root, part));
    }
    let members: Vec<EntityId> = part
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(root))
        .map(|(id, _)| *id)
        .collect();
    let [member] = members.as_slice() else {
        return Err(Error::Other(format!(
            "{verb} definition must be exactly one member"
        )));
    };
    let member = *member;
    part.entities.remove(&root);
    part.entities.get_mut(&member).unwrap().parent = None;
    Ok((member, part))
}

fn derived_id(parent: EntityId, rec: &EntityRecord) -> EntityId {
    let mut h = blake3::Hasher::new();
    h.update(parent.0.as_bytes());
    h.update(&[0]);
    h.update(format!("{:?}", rec.kind).as_bytes());
    h.update(&[0]);
    h.update(rec.name.as_bytes());
    h.update(&[0]);
    h.update(&rec.ordinal.to_le_bytes());
    let hash = h.finalize();
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&hash.as_bytes()[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x80;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    EntityId(uuid::Uuid::from_bytes(bytes))
}

fn remap_tree(
    store: &dyn Store,
    tree: BTreeMap<EntityId, EntityRecord>,
    root_old: EntityId,
    root_new: EntityId,
    prev: Option<&Snapshot>,
) -> Result<BTreeMap<EntityId, EntityRecord>> {
    let mut id_map = BTreeMap::new();
    id_map.insert(root_old, root_new);
    let mut taken = BTreeSet::from([root_new]);
    let mut queue = vec![root_old];
    while let Some(old) = queue.pop() {
        let parent_new = id_map[&old];
        let mut kids: Vec<(EntityId, EntityRecord)> = tree
            .iter()
            .filter(|(_, r)| r.parent == Some(old))
            .map(|(i, r)| (*i, r.clone()))
            .collect();
        kids.sort_by_key(|(_, r)| r.ordinal);
        for (old_id, rec) in kids {
            let new_id = match prev {
                Some(prev) => {
                    let key = SigKey::new(Some(parent_new), &rec.file, rec.kind, rec.name.clone());
                    prev.entities
                        .iter()
                        .find_map(|(pid, r)| {
                            (!taken.contains(pid) && r.sig_key() == key).then_some(*pid)
                        })
                        .unwrap_or_else(|| derived_id(parent_new, &rec))
                }
                None => derived_id(parent_new, &rec),
            };
            taken.insert(new_id);
            id_map.insert(old_id, new_id);
            queue.push(old_id);
        }
    }
    let mut out = BTreeMap::new();
    for (old, rec) in &tree {
        let new_id = *id_map.get(old).unwrap_or(old);
        let mut rec = rec.clone();
        rec.parent = rec.parent.map(|p| *id_map.get(&p).unwrap_or(&p));
        let bytes = remap_bytes(&store.get_bytes_blob(rec.bytes)?, &id_map)?;
        let content = Content {
            tokens: remap_tokens(store.get_content(rec.content)?.tokens, &id_map),
        };
        rec.bytes = store.put_bytes_blob(&bytes)?;
        rec.content = store.put_content(&content)?;
        out.insert(new_id, rec);
    }
    Ok(out)
}

fn remap_id(id: EntityId, map: &BTreeMap<EntityId, EntityId>) -> EntityId {
    if id == EntityId::SELF {
        id
    } else {
        *map.get(&id).unwrap_or(&id)
    }
}

fn remap_bytes(bytes: &Bytes, map: &BTreeMap<EntityId, EntityId>) -> Result<Bytes> {
    let chunks: Vec<Chunk> = bytes
        .chunks()
        .iter()
        .map(|c| match c {
            Chunk::Child(id) => Chunk::Child(remap_id(*id, map)),
            Chunk::Name(id) => Chunk::Name(remap_id(*id, map)),
            Chunk::ShorthandName { id, field } => Chunk::ShorthandName {
                id: remap_id(*id, map),
                field: field.clone(),
            },
            other => other.clone(),
        })
        .collect();
    let locals: Vec<(ByteRange, IdentRef)> = bytes
        .local_ranges()
        .iter()
        .map(|(r, ident)| {
            let ident = match ident {
                IdentRef::Entity(id) => IdentRef::Entity(remap_id(*id, map)),
                other => other.clone(),
            };
            (*r, ident)
        })
        .collect();
    Bytes::new(bytes.src().to_vec(), chunks, locals)
}

fn remap_tokens(tokens: Vec<Token>, map: &BTreeMap<EntityId, EntityId>) -> Vec<Token> {
    tokens
        .into_iter()
        .map(|t| match t {
            Token::Child(id) => Token::Child(remap_id(id, map)),
            Token::Ident(IdentRef::Entity(id)) => Token::Ident(IdentRef::Entity(remap_id(id, map))),
            other => other,
        })
        .collect()
}

/// Keep the entity's leading trivia (blank lines / docs / attributes attached
/// by extent) and tolerate a missing trailing newline.
fn item_text(store: &dyn Store, snap: &Snapshot, id: EntityId, text: &[u8]) -> Result<Vec<u8>> {
    let (old, _) = super::render_entity(snap, store, id, false)?;
    let old_lead = leading_trivia_len(&old);
    let new_ws = text.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let new_lead = leading_trivia_len(text);
    let mut out = Vec::new();
    // A definition that starts at the item (`fn f`, `isValid()`) must not wipe
    // `///` / `#[attr]` that extent glued onto this entity.
    if new_lead == new_ws && old_lead > 0 {
        out.extend_from_slice(&old[..old_lead]);
        let rest = {
            let n = text.iter().take_while(|b| b.is_ascii_whitespace()).count();
            &text[n..]
        };
        out.extend_from_slice(rest);
    } else {
        out.extend_from_slice(text);
    }
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    Ok(out)
}

/// Whitespace, `//`/`///` line comments, `/* */` blocks, and `#[]` / `#![]`
/// attributes. Stops at the item keyword (`fn`, `pub`, `isValid`, …).
fn leading_trivia_len(src: &[u8]) -> usize {
    let mut i = 0;
    loop {
        while i < src.len() && src[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= src.len() {
            return i;
        }
        if src[i] == b'/' && src.get(i + 1) == Some(&b'/') {
            while i < src.len() && src[i] != b'\n' {
                i += 1;
            }
            continue;
        }
        if src[i] == b'/' && src.get(i + 1) == Some(&b'*') {
            i += 2;
            while i + 1 < src.len() && !(src[i] == b'*' && src[i + 1] == b'/') {
                i += 1;
            }
            i = i.saturating_add(2).min(src.len());
            continue;
        }
        if src[i] == b'#' {
            let mut j = i + 1;
            if src.get(j) == Some(&b'!') {
                j += 1;
            }
            if src.get(j) == Some(&b'[') {
                j += 1;
                let mut depth = 1usize;
                while j < src.len() && depth > 0 {
                    match src[j] {
                        b'[' => depth += 1,
                        b']' => depth -= 1,
                        _ => {}
                    }
                    j += 1;
                }
                i = j;
                continue;
            }
        }
        return i;
    }
}

/// Re-indent `id` and everything nested in it from the level it had to the level of its
/// new parent (`None` = column 0), by the first code line's leading whitespace.
fn reindent_subtree(
    store: &dyn Store,
    snap: &mut Snapshot,
    id: EntityId,
    new_parent: Option<EntityId>,
) -> Result<()> {
    let (rendered, _) = render_entity(snap, store, id, false)?;
    let lead = rendered.iter().take_while(|b| b.is_ascii_whitespace()).count();
    let line_start = rendered[..lead].iter().rposition(|b| *b == b'\n').map_or(0, |p| p + 1);
    let from = rendered[line_start..lead].to_vec();
    let to = new_parent
        .map(|p| sibling_indent(store, snap, p))
        .unwrap_or_default();
    if from == to {
        return Ok(());
    }
    for eid in subtree(snap, id) {
        let rec = &snap.entities[&eid];
        let bytes = store.get_bytes_blob(rec.bytes)?.reindent(&from, &to)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        snap.entities.get_mut(&eid).unwrap().bytes = bytes_id;
    }
    Ok(())
}

/// After roots of `file` were reordered: the first root starts at column 0 with no blank
/// line above it, every later root starts on a fresh line with one blank line before it —
/// unless it already begins with a newline, in which case its own trivia is kept. The
/// separator between two items lives in the second one's leading text, so an item moved
/// to or from the front would otherwise render glued (`}fn`) or leave a blank first line.
fn normalize_root_separators(store: &dyn Store, snap: &mut Snapshot, file: &RelPath) -> Result<()> {
    for (i, id) in snap.file_roots(file).into_iter().enumerate() {
        let rec = &snap.entities[&id];
        let bytes = store.get_bytes_blob(rec.bytes)?;
        let lead = bytes
            .chunks()
            .first()
            .and_then(|c| match c {
                Chunk::Literal(r) => Some(
                    bytes.src()[r.start as usize..r.end as usize]
                        .iter()
                        .take_while(|b| **b == b'\n')
                        .count(),
                ),
                _ => None,
            });
        let want = match (i, lead) {
            (0, Some(l)) if l > 0 => 0,
            (_, Some(0)) if i > 0 => 2,
            _ => continue,
        };
        let fixed = bytes.with_leading_newlines(want)?;
        let bytes_id = store.put_bytes_blob(&fixed)?;
        snap.entities.get_mut(&id).unwrap().bytes = bytes_id;
    }
    Ok(())
}

/// Indentation of `parent`'s existing members (the whitespace after the last newline
/// before the first member's text); four spaces when it has none yet.
fn sibling_indent(store: &dyn Store, snap: &Snapshot, parent: EntityId) -> Vec<u8> {
    let first = snap
        .entities
        .iter()
        .filter(|(_, r)| r.parent == Some(parent))
        .min_by_key(|(_, r)| r.ordinal)
        .map(|(id, _)| *id);
    let indent = first
        .and_then(|id| render_entity(snap, store, id, false).ok())
        .and_then(|(bytes, _)| {
            let lead = bytes.iter().take_while(|b| b.is_ascii_whitespace()).count();
            let last_nl = bytes[..lead].iter().rposition(|b| *b == b'\n')?;
            Some(bytes[last_nl + 1..lead].to_vec())
        });
    indent
        .filter(|i| !i.is_empty())
        .unwrap_or_else(|| b"    ".to_vec())
}

/// A new item needs a blank line before it or render glues `}fn` / `;fn`. Nested items
/// (an impl method, a class member) are also indented one level when the body an
/// agent passes is written at column 0; a body that arrives indented is kept as is.
/// Only text that begins with its own newline is taken as already laid out.
fn add_def_text(parent: Option<EntityId>, indent: &[u8], text: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let laid_out = text.first() == Some(&b'\n');
    let indented = text.first().is_some_and(|b| *b == b' ' || *b == b'\t');
    if !laid_out {
        out.extend_from_slice(b"\n\n");
    }
    if parent.is_some() && !laid_out && !indented {
        for (i, line) in text.split(|b| *b == b'\n').enumerate() {
            if i > 0 {
                out.push(b'\n');
            }
            if !line.is_empty() {
                out.extend_from_slice(indent);
                out.extend_from_slice(line);
            }
        }
    } else {
        out.extend_from_slice(text);
    }
    if !out.ends_with(b"\n") {
        out.push(b'\n');
    }
    out
}

